def attach_particle(word: str, particle: str) -> str:
    # Sino-Korean numbers
    sino_korean = {
        '0': '영', '1': '일', '2': '이', '3': '삼', '4': '사',
        '5': '오', '6': '육', '7': '칠', '8': '팔', '9': '구'
    }

    # Get the last character
    last_char = word[-1]

    # Check if it's a digit
    if last_char.isdigit():
        # Convert digit to Sino-Korean pronunciation
        last_sound = sino_korean[last_char]
        has_batchim = has_final_consonant(last_sound)
    else:
        # It's a Hangul character
        has_batchim = has_final_consonant(last_char)

    # Special case for "으로/로": ㄹ batchim is treated as vowel
    if particle == "으로/로" and last_char not in sino_korean and last_char.isalpha():
        # Check if the final consonant is ㄹ (rieul)
        code = ord(last_char)
        if 0xAC00 <= code <= 0xD7A3:
            final_index = (code - 0xAC00) % 28
            if final_index == 8:  # ㄹ is the 8th final consonant
                has_batchim = False

    # Select the appropriate particle form
    if particle == "은/는":
        return word + ("은" if has_batchim else "는")
    elif particle == "이/가":
        return word + ("이" if has_batchim else "가")
    elif particle == "을/를":
        return word + ("을" if has_batchim else "를")
    elif particle == "과/와":
        return word + ("과" if has_batchim else "와")
    elif particle == "으로/로":
        return word + ("으로" if has_batchim else "로")

    return word

def has_final_consonant(char: str) -> bool:
    """Check if a Hangul syllable has a final consonant (batchim)."""
    code = ord(char)

    # Check if it's a Hangul syllable
    if 0xAC00 <= code <= 0xD7A3:
        # Hangul syllable structure: (initial × 588) + (medial × 28) + final
        # final ranges from 0 to 27, where 0 means no final consonant
        final_index = (code - 0xAC00) % 28
        return final_index != 0

    return False

